message.content:
{
    "memory": [
        {
            "id": "0",
            "text": "Pregnancy at twenty-seven weeks brings an array of physical and emotional changes.",
            "event": "ADD"
        },
        {
            "id": "0",
            "text": "A growing belly is the most noticeable physical change during this stage.",
            "event": "ADD"
        },
        {
            "id": "0",
            "text": "Increased vaginal discharge, swollen hands and feet, leg cramps, varicose veins, stretch marks are other physical changes.",
            "event": "ADD"
        },
        {
            "id": "0",
            "text": "The twenty-seventh week of pregnancy may bring emotional ups and downs, mood swings, anxiety, and irritability.",
            "event": "ADD"
        },
        {
            "id": "0",
            "text": "Prenatal exercises like yoga or swimming can help with backaches and improve overall well-being.",
            "event": "ADD"
        },
        {
            "id": "0",
            "text": "Eating smaller meals throughout the day, avoiding spicy or fatty foods, and propping up pillows for support may alleviate heartburn.",
            "event": "ADD"
        },
        {
            "id": "0",
            "text": "Staying hydrated and engaging in regular physical activity can also help combat constipation.",
            "event": "ADD"
        }
    ]
}

